(function(){["dsp","cc","pod","dwc"].forEach(function(prefix){const drop=document.getElementById(prefix+"-drop"),file=document.getElementById(prefix+"-file"),name=document.getElementById(prefix+"-file-name");if(!drop||!file||!name)return;file.addEventListener("change",function(){name.textContent=file.files.length?file.files[0].name:"No file selected"});["dragenter","dragover"].forEach(function(type){drop.addEventListener(type,function(e){e.preventDefault();drop.classList.add("is-dragging")})});["dragleave","drop"].forEach(function(type){drop.addEventListener(type,function(e){e.preventDefault();drop.classList.remove("is-dragging")})});drop.addEventListener("drop",function(e){if(e.dataTransfer&&e.dataTransfer.files.length){file.files=e.dataTransfer.files;file.dispatchEvent(new Event("change"))}})})})();
